def path_sum(node, targetSum):
    def dfsHelper(node, curSum):

        if node is None:
            if curSum == targetSum:
                return True
            else:
                return False
        else:
            curSum += node.val
            is_left = dfsHelper(node.left, curSum)
            is_right = dfsHelper(node.right, curSum)

        return is_left or is_right

    dfsHelper(node, 0)

    return dfsHelper(node, 0)
